INSERT INTO ${tableName} (	DOCUMENT_ID, 
							CD4_COUNT, 
							CD4_PERCENT, 
							COLLECTION_DATE, 
							CLOSEST_TO_CURRENT_DX, 
							FIRST_LOW_CD4,
							FACILITY_NAME,
							FACILITY_EHARS_UID,
							CLIA,
							LAB_NAME,
							PROV_NAME,
							PROV_FNAME, 
							PROV_LNAME, 
							PROV_MNAME, 
							PROV_SUFFIX,
							MANUFACTURER,
							UPDATED_BY, 
							UPDATED_DATE)
VALUES
							(#{rawAcrfCd4Tst.documentId} 
							, #{rawAcrfCd4Tst.cd4Count:DECIMAL} 
							, #{rawAcrfCd4Tst.cd4Percent:DECIMAL} 
							, #{rawAcrfCd4Tst.collectionDate}   
							, #{rawAcrfCd4Tst.closestToCurrentDx} 
							, #{rawAcrfCd4Tst.firstLowCd4}
							, #{rawAcrfCd4Tst.facilityName,jdbcType=VARCHAR}
							, #{rawAcrfCd4Tst.facilityEharsUid,jdbcType=VARCHAR}
							, #{rawAcrfCd4Tst.clia,jdbcType=VARCHAR}
							, #{rawAcrfCd4Tst.labName,jdbcType=VARCHAR}
							, #{rawAcrfCd4Tst.providerName,jdbcType=VARCHAR}
							, #{rawAcrfCd4Tst.providerFname,jdbcType=VARCHAR}
							, #{rawAcrfCd4Tst.providerLname,jdbcType=VARCHAR}
							, #{rawAcrfCd4Tst.providerMname,jdbcType=VARCHAR}
							, #{rawAcrfCd4Tst.providerSuffix,jdbcType=VARCHAR}
							, #{rawAcrfCd4Tst.manufacturer,jdbcType=VARCHAR}
							, #{workerId,jdbcType=VARCHAR}
							, SYSDATE
							)

