UPDATE ${tableName} 
			SET
				CD4_COUNT=#{rawAcrfCd4Tst.cd4Count:DECIMAL}
			,	CD4_PERCENT=#{rawAcrfCd4Tst.cd4Percent:DECIMAL}
			, 	COLLECTION_DATE=#{rawAcrfCd4Tst.collectionDate} 
			,	CLOSEST_TO_CURRENT_DX=#{rawAcrfCd4Tst.closestToCurrentDx}
			, 	FIRST_LOW_CD4 = #{rawAcrfCd4Tst.firstLowCd4}
			, 	FACILITY_NAME = #{rawAcrfCd4Tst.facilityName,jdbcType=VARCHAR}
			, 	FACILITY_EHARS_UID = #{rawAcrfCd4Tst.facilityEharsUid,jdbcType=VARCHAR}
			, 	CLIA = #{rawAcrfCd4Tst.clia,jdbcType=VARCHAR}
			, 	LAB_NAME = #{rawAcrfCd4Tst.labName,jdbcType=VARCHAR}
			, 	PROV_NAME = #{rawAcrfCd4Tst.providerName,jdbcType=VARCHAR}
			, 	PROV_FNAME = #{rawAcrfCd4Tst.providerFname,jdbcType=VARCHAR}
			, 	PROV_LNAME = #{rawAcrfCd4Tst.providerLname,jdbcType=VARCHAR}
			, 	PROV_MNAME = #{rawAcrfCd4Tst.providerMname,jdbcType=VARCHAR}
			, 	PROV_SUFFIX = #{rawAcrfCd4Tst.providerSuffix,jdbcType=VARCHAR}
			, 	MANUFACTURER = #{rawAcrfCd4Tst.manufacturer,jdbcType=VARCHAR}
			, UPDATED_BY = #{workerId,jdbcType=VARCHAR}  
			, UPDATED_DATE = SYSDATE
WHERE			
			DOCUMENT_ID=#{rawAcrfCd4Tst.documentId}	AND CD4_SRC_ID=#{rawAcrfCd4Tst.cd4SrcId}



SELECT 
			  rowid arvSrcId, ARV_USE_TYPE arvUseType, ARV_MEDICATION arvMedications, ARV_BEGIN_DATE arvMedicationsDateBegan, ARV_END_DATE arvMedicationsDateOfLastUse, ARV_OTHER_USE_TYPE otherArvUseType 
FROM 
			${tableName} 
WHERE 
			${CRF_COLUMN_ID}=#{documentId}

