SELECT ACRF_RESULT_CODE acrfResultCode, ACRF_RESULT_DESC acrfResultDesc, PARENT_TEST_TYPE parentTestType, ACRF_TEST_CODE acrfTestCode, ACRF_REVISION acrfRevison FROM CODED_ACRF_TEST_RESULT where END_DATE is null and (ACRF_REVISION is null or ACRF_REVISION like '%'||#{acrfRevison}||'%')
and PARENT_TEST_TYPE=#{parentTestType} AND ACRF_TEST_CODE=#{acrfTestCode}
order by SORT_ORDER asc
